#!/usr/bin/env python3
# structdump.py: generate C functions that print every leaf field of structs in nvenc_drv.h by name (nested structs and
# arrays expanded), to decode picture setup controls field by field (T6.05).
#   scripts/structdump.py nvenc_drv.h out.h nvenc_h264_me_control_s nvenc_h265_md_control_s ...
# Each struct T gets: static void dump_T(const T *a, const T *b, const char *pfx)  (b == NULL: print a; else only diffs)
import re, sys

src = open(sys.argv[1]).read()
src = re.sub(r'/\*.*?\*/', '', src, flags=re.S)
src = re.sub(r'//[^\n]*', '', src)
structs = {}
for m in re.finditer(r'typedef\s+struct\s*\{(.*?)\}\s*(\w+)\s*;', src, re.S):
    structs[m.group(2)] = m.group(1)

def members(body):
    out = []
    for decl in body.split(';'):
        decl = ' '.join(decl.split())
        if not decl: continue
        decl = re.sub(r'\s*:\s*\d+$', '', decl)                    # bit width
        m = re.match(r'(.*?)(\w+)\s*((?:\[\s*\w+\s*\])*)$', decl)
        if not m: continue
        typ, name, dims = m.group(1).strip(), m.group(2), re.findall(r'\[\s*(\w+)\s*\]', m.group(3))
        if name.startswith('reserved') or name.startswith('pad'): continue
        out.append((typ, name, dims))
    return out

def gen(sname, lines, depth=0):
    for typ, name, dims in members(structs[sname]):
        idx = ''.join('[i%d]' % (depth * 4 + k) for k in range(len(dims)))
        loops = ''.join('for (int i%d = 0; i%d < %s; i%d++) ' % (depth * 4 + k, depth * 4 + k, d, depth * 4 + k) for k, d in enumerate(dims))
        base = typ.split()[-1]
        if base in structs:
            lines.append('    %s{ const %s *sa = &a->%s%s, *sb = b ? &b->%s%s : NULL; char p%d[160]; snprintf(p%d, sizeof p%d, "%%s%s%s.", pfx%s);'
                         % (loops, base, name, idx, name, idx, depth, depth, depth, name, '[%d]' * len(dims),
                            ''.join(', i%d' % (depth * 4 + k) for k in range(len(dims)))))
            lines.append('      dump_%s(sa, sb, p%d); }' % (base, depth))
        else:
            fmt = '%s%s%s' % ('%s', name, '[%d]' * len(dims))
            args = ''.join(', i%d' % (depth * 4 + k) for k in range(len(dims)))
            lines.append('    %s{ long long va = (long long)a->%s%s, vb = b ? (long long)b->%s%s : va; if (!b ? va != 0 : va != vb) { char n[160]; snprintf(n, sizeof n, "%s", pfx%s);'
                         % (loops, name, idx, name, idx, fmt, args))
            lines.append('      if (b) printf("  %-52s %lld -> %lld\\n", n, va, vb); else printf("  %-52s %lld (0x%llx)\\n", n, va, (unsigned long long)va); } }')

out = ['// generated by scripts/structdump.py from nvenc_drv.h; do not edit', '#pragma once', '#include <stdio.h>']
needed, order = list(sys.argv[3:]), []
def collect(s):
    for typ, _, _ in members(structs[s]):
        b = typ.split()[-1]
        if b in structs and b not in order: collect(b)
    if s not in order: order.append(s)
for s in needed: collect(s)
for s in order: out.append('static void dump_%s(const %s *a, const %s *b, const char *pfx);' % (s, s, s))
for s in order:
    out.append('static void dump_%s(const %s *a, const %s *b, const char *pfx)\n{' % (s, s, s))
    body = []; gen(s, body); out += body; out.append('}')
open(sys.argv[2], 'w').write('\n'.join(out) + '\n')
print('wrote', sys.argv[2], 'for', ', '.join(order))
